$json$::jsonb
  ) AS x(
    "legacySourceId" text,
    name text,
    "typeRaw" text,
    ages text,
    address text,
    neighborhood text,
    ownership text,
    phone text,
    "verificationRaw" text,
    "sourceUrl" text,
    latitude numeric,
    longitude numeric,
    manual boolean
  )
)
INSERT INTO public.institutions (
  legacy_source_id, name, type, ownership, age_range_text, address, neighborhood, city,
  phone, latitude, longitude, verification_status, source_name, source_url, crm_status, metadata
)
SELECT
  "legacySourceId",
  name,
  CASE
    WHEN coalesce("typeRaw", '') LIKE '%משפחתון%' THEN 'FAMILY_DAYCARE'::institution_type
    WHEN coalesce("typeRaw", '') LIKE '%פעוטון%' THEN 'NURSERY'::institution_type
    WHEN coalesce("typeRaw", '') LIKE '%מעון%' THEN 'DAYCARE'::institution_type
    WHEN coalesce("typeRaw", '') LIKE '%גן%' OR coalesce("typeRaw", '') LIKE '%חובה%' OR coalesce("typeRaw", '') LIKE '%טרום%' THEN
      CASE WHEN ownership = 'פרטי' THEN 'PRIVATE_KINDERGARTEN'::institution_type ELSE 'MUNICIPAL_KINDERGARTEN'::institution_type END
    ELSE 'OTHER'::institution_type
  END,
  ownership,
  ages,
  address,
  neighborhood,
  'כרמיאל',
  phone,
  latitude,
  longitude,
  CASE
    WHEN coalesce("verificationRaw", '') LIKE '%דורש אימות%' THEN 'NEEDS_VERIFICATION'::verification_status
    WHEN coalesce("verificationRaw", '') LIKE '%✅%' OR coalesce("verificationRaw", '') LIKE '%רשמי%' OR coalesce("verificationRaw", '') LIKE '%התאחדות%' THEN 'VERIFIED'::verification_status
    WHEN coalesce("verificationRaw", '') <> '' THEN 'PARTIAL'::verification_status
    ELSE 'UNVERIFIED'::verification_status
  END,
  coalesce("verificationRaw", 'Seed imported from Karmiel PDF'),
  "sourceUrl",
  'PROSPECT'::crm_status,
  jsonb_build_object(
    'typeRaw', "typeRaw",
    'verificationRaw', "verificationRaw",
    'manual', manual,
    'importedFrom', 'karmiel-institutions-seed.json'
  )
FROM seed
ON CONFLICT (legacy_source_id) WHERE legacy_source_id IS NOT NULL
DO UPDATE SET
  name = EXCLUDED.name,
  type = EXCLUDED.type,
  ownership = EXCLUDED.ownership,
  age_range_text = EXCLUDED.age_range_text,
  address = EXCLUDED.address,
  neighborhood = EXCLUDED.neighborhood,
  phone = EXCLUDED.phone,
  latitude = EXCLUDED.latitude,
  longitude = EXCLUDED.longitude,
  verification_status = EXCLUDED.verification_status,
  source_name = EXCLUDED.source_name,
  source_url = EXCLUDED.source_url,
  metadata = EXCLUDED.metadata,
  updated_at = now();

-- Sanity check
SELECT
  count(*) AS institutions,
  count(*) FILTER (WHERE phone IS NOT NULL) AS with_phone,
  count(*) FILTER (WHERE neighborhood ILIKE '%גבעת רם%') AS givat_ram,
  count(*) FILTER (WHERE verification_status IN ('NEEDS_VERIFICATION','UNVERIFIED')) AS needs_verification
FROM public.institutions;
